def insert_sorted(xs: list[int], v: int) -> list[int]:
    def find_position(xs, v, start, end):
        if start == end:
            if xs[start] > v:
                return start
            else:
                return start + 1
        elif start > end:
            return start

        mid = (start + end) // 2
        if xs[mid] == v:
            return mid + 1
        elif xs[mid] < v:
            return find_position(xs, v, mid + 1, end)
        else:
            return find_position(xs, v, start, mid - 1)

    pos = find_position(xs, v, 0, len(xs) - 1)
    return xs[:pos] + [v] + xs[pos:]

